// square-grid.js — the xy triangle and the unit square spektrafilm's tables are indexed by.
//
// u = (1 − x)², v = y / (1 − x) maps the triangle x ≥ 0, y ≥ 0, x + y ≤ 1 onto the unit square; the inverse is
// x = 1 − √u, y = v·√u. An n × n table has nodes at u, v = i/(n − 1). Move the pointer over either panel: the
// point is drawn in both, with the cell it falls in for the chosen table size. The cells drawn on the left are the
// table's cells as they land in xy: wide where x is small, narrow near x = 1.
// DATA is generated by work/ch1/make_sketches.js from the engine's data.json; do not edit by hand.
const DATA = {"locus":[[380,0.17411,0.00496],[385,0.17401,0.00498],[390,0.1738,0.00492],[395,0.17356,0.00492],[400,0.17334,0.0048],[405,0.17302,0.00478],[410,0.17258,0.0048],[415,0.17209,0.00483],[420,0.17141,0.0051],[425,0.1703,0.00579],[430,0.16888,0.0069],[435,0.1669,0.00856],[440,0.16441,0.01086],[445,0.1611,0.01379],[450,0.15664,0.0177],[455,0.15099,0.02274],[460,0.14396,0.0297],[465,0.1355,0.03988],[470,0.12412,0.0578],[475,0.10959,0.08684],[480,0.09129,0.1327],[485,0.06871,0.20072],[490,0.04539,0.29498],[495,0.02346,0.4127],[500,0.00817,0.53842],[505,0.00386,0.65482],[510,0.01387,0.75019],[515,0.03885,0.81202],[520,0.0743,0.8338],[525,0.11416,0.82621],[530,0.15472,0.80586],[535,0.19288,0.78163],[540,0.22962,0.75433],[545,0.26578,0.72432],[550,0.3016,0.69231],[555,0.33736,0.65885],[560,0.3731,0.62445],[565,0.40874,0.58961],[570,0.44406,0.55471],[575,0.47877,0.5202],[580,0.51249,0.48659],[585,0.54479,0.45443],[590,0.57515,0.42423],[595,0.60293,0.3965],[600,0.62704,0.37249],[605,0.64823,0.35139],[610,0.66576,0.33401],[615,0.68008,0.31975],[620,0.6915,0.30834],[625,0.70061,0.2993],[630,0.70792,0.29203],[635,0.71403,0.28593],[640,0.71903,0.28093],[645,0.72303,0.27695],[650,0.72599,0.27401],[655,0.72827,0.27173],[660,0.72997,0.27003],[665,0.73109,0.26891],[670,0.73199,0.26801],[675,0.73272,0.26728],[680,0.73342,0.26658],[685,0.73405,0.26595],[690,0.73439,0.26561],[695,0.73459,0.26541],[700,0.73469,0.26531]],"srgb":[[0.6401,0.33],[0.3,0.6],[0.15,0.06]],"D55":[0.3324,0.3474],"mr":[0.4913,0.3207]};
exports.meta = {
  title: 'Triangle to square', chapter: '1',
  about: 'Pointer over either panel: a chromaticity, its table coordinates, and the table cell it falls in.',
  size: [600, 330],
  params: {
    n: { value: 16, options: [4, 8, 16, 64, 192], label: 'table size n' },
    gamut: { value: true, label: 'show sRGB gamut' },
  },
};
const INK = '#1a1a1a', MUT = '#737373', ACC = '#e2001a', HAIR = '#d6d6d6';
const tq = (x, y) => [(1 - x) ** 2, y / Math.max(1 - x, 1e-10)];
const qt = (u, v) => [1 - Math.sqrt(u), v * Math.sqrt(u)];
const S = 250, A = { L: 30, T: 40 }, B = { L: 330, T: 40 };
const toA = (x, y) => [A.L + x * S, A.T + S - y * S], toB = (u, v) => [B.L + u * S, B.T + S - v * S];
function poly(ctx, pts) { ctx.beginPath(); pts.forEach(([x, y], i) => (i ? ctx.lineTo(x, y) : ctx.moveTo(x, y))); ctx.stroke(); }
function dense(p, k) { const o = []; for (let i = 0; i + 1 < p.length; i++) for (let j = 0; j < k; j++) { const t = j / k; o.push([p[i][0] + (p[i + 1][0] - p[i][0]) * t, p[i][1] + (p[i + 1][1] - p[i][1]) * t]); } o.push(p[p.length - 1]); return o; }

exports.draw = (ctx, env) => {
  const { w, h, params, mouse } = env, n = +params.n;
  ctx.fillStyle = '#ffffff'; ctx.fillRect(0, 0, w, h); ctx.font = '11px Arial'; ctx.lineWidth = 1;
  ctx.fillStyle = MUT; ctx.fillText('xy CHROMATICITY', A.L, 24); ctx.fillText(`TABLE COORDINATES (u, v), ${n} × ${n}`, B.L, 24);
  // cells: constant u is a vertical line in xy; constant v is a line through (1, 0)
  const step = n > 32 ? Math.ceil(n / 32) : 1;
  ctx.strokeStyle = HAIR;
  for (let i = 0; i < n; i += step) {
    const t = i / (n - 1), x = 1 - Math.sqrt(t);
    poly(ctx, [toA(x, 0), toA(x, 1 - x)]); poly(ctx, [toA(0, t), toA(1, 0)]);
    poly(ctx, [toB(t, 0), toB(t, 1)]); poly(ctx, [toB(0, t), toB(1, t)]);
  }
  ctx.strokeStyle = MUT; poly(ctx, [toA(0, 0), toA(1, 0), toA(0, 1), toA(0, 0)]); poly(ctx, [toB(0, 0), toB(1, 0), toB(1, 1), toB(0, 1), toB(0, 0)]);
  const loc = DATA.locus.map((p) => [p[1], p[2]]); loc.push(loc[0]);
  ctx.strokeStyle = INK; ctx.lineWidth = 1.4; poly(ctx, loc.map(([x, y]) => toA(x, y))); poly(ctx, dense(loc, 20).map(([x, y]) => toB(...tq(x, y))));
  if (params.gamut) {
    const g = DATA.srgb.concat([DATA.srgb[0]]); ctx.setLineDash([4, 3]); ctx.lineWidth = 1;
    poly(ctx, g.map(([x, y]) => toA(x, y))); poly(ctx, dense(g, 40).map(([x, y]) => toB(...tq(x, y)))); ctx.setLineDash([]);
  }
  ctx.lineWidth = 1;
  // the pointer, in whichever panel it is
  let x, y;
  if (mouse.x >= B.L && mouse.x <= B.L + S && mouse.y >= B.T && mouse.y <= B.T + S) [x, y] = qt((mouse.x - B.L) / S, (B.T + S - mouse.y) / S);
  else if (mouse.x >= A.L && mouse.x <= A.L + S && mouse.y >= A.T && mouse.y <= A.T + S) { x = (mouse.x - A.L) / S; y = (A.T + S - mouse.y) / S; if (x + y > 1) { const k = 1 / (x + y); x *= k; y *= k; } }
  else [x, y] = DATA.mr;
  const [u, v] = tq(x, y), fu = u * (n - 1), fv = v * (n - 1), i0 = Math.min(Math.floor(fu), n - 2), j0 = Math.min(Math.floor(fv), n - 2);
  // highlight the cell in both panels
  const cellA = [], cellB = [[i0, j0], [i0 + 1, j0], [i0 + 1, j0 + 1], [i0, j0 + 1], [i0, j0]].map(([a, b]) => [a / (n - 1), b / (n - 1)]);
  for (let k = 0; k + 1 < cellB.length; k++) for (let s = 0; s <= 10; s++) { const t = s / 10; cellA.push(qt(cellB[k][0] + (cellB[k + 1][0] - cellB[k][0]) * t, cellB[k][1] + (cellB[k + 1][1] - cellB[k][1]) * t)); }
  ctx.fillStyle = 'rgba(226,0,26,0.12)';
  ctx.beginPath(); cellA.forEach(([a, b], k) => { const [px, py] = toA(a, b); k ? ctx.lineTo(px, py) : ctx.moveTo(px, py); }); ctx.fill();
  ctx.beginPath(); cellB.forEach(([a, b], k) => { const [px, py] = toB(a, b); k ? ctx.lineTo(px, py) : ctx.moveTo(px, py); }); ctx.fill();
  ctx.fillStyle = ACC; for (const [px, py] of [toA(x, y), toB(u, v)]) { ctx.beginPath(); ctx.arc(px, py, 3.5, 0, 7); ctx.fill(); }
  const [dx, dy] = toA(...DATA.D55); ctx.strokeStyle = INK; ctx.beginPath(); ctx.arc(dx, dy, 3, 0, 7); ctx.stroke();
  const [ex, ey] = toB(...tq(...DATA.D55)); ctx.beginPath(); ctx.arc(ex, ey, 3, 0, 7); ctx.stroke();
  ctx.fillStyle = INK;
  ctx.fillText(`x = ${x.toFixed(4)}, y = ${y.toFixed(4)}  →  u = ${u.toFixed(4)}, v = ${v.toFixed(4)}`, A.L, h - 26);
  ctx.fillText(`cell (${i0}, ${j0}) of ${n} × ${n}, weights a = ${(fu - i0).toFixed(3)}, b = ${(fv - j0).toFixed(3)}`, A.L, h - 10);
  ctx.fillStyle = MUT; ctx.textAlign = 'right'; ctx.fillText('open circle: D55', w - 10, h - 10); ctx.textAlign = 'left';
};
